-- Audyt E24: tabele bez RLS lub z politykami bez warunku (produkcja).
-- Kod: -1 brak tabeli, bity 1 RLS włączone, 2/4/8/16 anon SELECT/INSERT/UPDATE/DELETE, 32/64/128/256 authenticated to samo.
-- Kolejność t00..: scripts/db-read/table-acl-audit.names, na końcu liczba wszystkich tabel public bez RLS z dowolnym prawem anon/authenticated.
select
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'e21_demo_templates_before') as t00,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'e21_repair_runs') as t01,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'example_table') as t02,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'konta_do_stworzenia') as t03,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'schema_migrations') as t04,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'stats_excluded_users') as t05,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'email_providers') as t06,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'marketing_ai_providers') as t07,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'marketing_cities') as t08,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'marketing_raw_contacts') as t09,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'marketing_search_logs') as t10,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'marketing_search_queries_log') as t11,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'marketing_verified_contacts') as t12,
  (select coalesce(max((case when c.relrowsecurity then 1 else 0 end) + (case when has_table_privilege('anon', c.oid, 'SELECT') then 2 else 0 end) + (case when has_table_privilege('anon', c.oid, 'INSERT') then 4 else 0 end) + (case when has_table_privilege('anon', c.oid, 'UPDATE') then 8 else 0 end) + (case when has_table_privilege('anon', c.oid, 'DELETE') then 16 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'SELECT') then 32 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'INSERT') then 64 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'UPDATE') then 128 else 0 end) + (case when has_table_privilege('authenticated', c.oid, 'DELETE') then 256 else 0 end)), -1) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relname = 'public_kv') as t13,
  (select count(*) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'public' and c.relkind in ('r','p') and not c.relrowsecurity and (has_table_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,DELETE') or has_table_privilege('authenticated', c.oid, 'SELECT,INSERT,UPDATE,DELETE'))) as norls_open
